#include <algorithm>
#include <fstream>
#include <set>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("lifeguards.in");
    std::ofstream out("lifeguards.out");
    int n; in >> n;
    std::vector<std::pair<long long, int>> events;
    for (int i=0; i<n; ++i) { long long a,b; in >> a >> b; events.push_back({a,i}); events.push_back({b,~i}); }
    std::sort(events.begin(), events.end());
    std::set<int> active;
    std::vector<long long> alone(n,0);
    long long total=0,previous=events.front().first;
    for (const auto& e: events) {
        const long long length=e.first-previous;
        if (!active.empty()) total+=length;
        if (active.size()==1) alone[*active.begin()]+=length;
        if (e.second>=0) active.insert(e.second); else active.erase(~e.second);
        previous=e.first;
    }
    out << total-*std::min_element(alone.begin(),alone.end()) << '\n';
}
