#include <algorithm>
#include <fstream>
#include <functional>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("rental.in");
    std::ofstream out("rental.out");
    int n,m,r; in >> n >> m >> r;
    std::vector<long long> cows(n),rents(r);
    for (auto& x:cows) in >> x;
    std::vector<std::pair<long long,long long>> shops(m);
    for (auto& s:shops) in >> s.second >> s.first;
    for (auto& x:rents) in >> x;
    std::sort(cows.begin(),cows.end(),std::greater<long long>());
    std::sort(shops.begin(),shops.end(),std::greater<std::pair<long long,long long>>());
    std::sort(rents.begin(),rents.end(),std::greater<long long>());
    std::vector<long long> rentPrefix(r+1,0);
    for(int i=0;i<r;++i) rentPrefix[i+1]=rentPrefix[i]+rents[i];
    long long milkRevenue=0,answer=rentPrefix[std::min(n,r)];
    int shop=0;
    for(int t=1;t<=n;++t) {
        long long remaining=cows[t-1];
        while(remaining>0 && shop<m) {
            const long long take=std::min(remaining,shops[shop].second);
            milkRevenue+=take*shops[shop].first;
            remaining-=take; shops[shop].second-=take;
            if(shops[shop].second==0) ++shop;
        }
        answer=std::max(answer,milkRevenue+rentPrefix[std::min(n-t,r)]);
    }
    out << answer << '\n';
}
