#include <queue>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("mootube.in");
    std::ofstream out("mootube.out");
    int n,q; in >> n >> q;
    std::vector<std::vector<std::pair<int,int>>> edges(n);
    for(int i=0;i<n-1;++i) {int u,v,w; in >> u >> v >> w; --u; --v; edges[u].push_back({v,w}); edges[v].push_back({u,w});}
    for(int i=0;i<q;++i) {
        int k,v; in >> k >> v; --v;
        std::vector<bool> seen(n,false); std::queue<int> pending;
        seen[v]=true; pending.push(v); int count=0;
        while(!pending.empty()) {
            const int u=pending.front(); pending.pop();
            for(const auto& edge:edges[u]) if(edge.second>=k && !seen[edge.first]) {
                seen[edge.first]=true; pending.push(edge.first); ++count;
            }
        }
        out << count << '\n';
    }
}
